INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload)
SELECT 'core-2026-09-v4','participle-clauses','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"participle-clauses","title":"Participle clauses and reduced relatives","level":"C1","order":61,"summary":"Make related information more compact while keeping the implied subject and time relationship clear.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["An active -ing clause","A passive participle clause","A completed earlier action","Reduced relative clauses"],"rules":[{"title":"An active -ing clause","explanation":"A present-participle clause can add a reason, simultaneous activity or result. In an introductory clause, its understood subject normally matches the main-clause subject. Its form does not by itself set a present tense; the main clause and context provide time.","pattern":"**Walking home**, she called her brother.","commonMistakes":["Walking home, the rain began suggests that the rain was walking. This is a dangling modifier."],"examples":["Add an active participle clause: “**preparing** the visitor guide, the assistant noticed a mistake.”","Add an active participle clause: “**restoring** the old portrait, the assistant noticed a mistake.”"],"skill":"form"},{"title":"A passive participle clause","explanation":"A past-participle clause usually has a passive meaning: the implied subject receives the action. It can express a condition, reason or accompanying description. The main clause supplies the participant and time.","pattern":"**Kept cool**, the food lasts longer.","commonMistakes":["A past participle does not automatically mean past time; it often marks passive meaning."],"examples":["Make the earlier completion explicit: “Having **prepared** the visitor guide, we took a break.”","Make the earlier completion explicit: “Having **restored** the old portrait, we took a break.”"],"skill":"meaning"},{"title":"A completed earlier action","explanation":"Use **having + past participle** to make completion before the main action explicit. The passive equivalent is having been + participle. This is useful when sequence might otherwise be unclear, but long chains of participles can become hard to read.","pattern":"**Having checked** the map, we left.","commonMistakes":["Having checking is not the perfect-participle form: having takes a past participle."],"examples":["Reduce “who is doing the task”: “The assistant **preparing** the visitor guide is new.”","Reduce “who is doing the task”: “The assistant **restoring** the old portrait is new.”"],"skill":"contrast"},{"title":"Reduced relative clauses","explanation":"An -ing phrase after a noun can correspond to an active relative clause; a past-participle phrase can correspond to a passive relative. Keep the relation close to its noun and ensure that the reduction preserves the intended meaning.","pattern":"The person **waiting outside** is here. / The letter **sent yesterday** arrived.","commonMistakes":["Not every finite relative clause can be reduced without changing its meaning, tense or emphasis."],"examples":["In “Having prepared the visitor guide, the assistant left”, who performed the earlier action? → **the assistant**","In “Having restored the old portrait, the assistant left”, who performed the earlier action? → **the assistant**"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-participles"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"chapter":{"introduction":["Make related information more compact while keeping the implied subject and time relationship clear.","The form tells you how to build the sentence; the context tells you why that form is useful. Read each section with both questions in mind. The examples make one contrast at a time, while the practice mixes the skills so that you learn to recognise the pattern yourself."],"rules":[{"title":"An active -ing clause","explanation":"A present-participle clause can add a reason, simultaneous activity or result. In an introductory clause, its understood subject normally matches the main-clause subject. Its form does not by itself set a present tense; the main clause and context provide time.","pattern":"**Walking home**, she called her brother.","commonMistakes":["Walking home, the rain began suggests that the rain was walking. This is a dangling modifier."],"examples":["Add an active participle clause: “**preparing** the visitor guide, the assistant noticed a mistake.”","Add an active participle clause: “**restoring** the old portrait, the assistant noticed a mistake.”"],"skill":"form","id":"participle-clauses-foundation-1","domain":"nonfinite","referenceIds":["bc-participles"],"readingVersion":"core-2026-09-v3"},{"title":"A passive participle clause","explanation":"A past-participle clause usually has a passive meaning: the implied subject receives the action. It can express a condition, reason or accompanying description. The main clause supplies the participant and time.","pattern":"**Kept cool**, the food lasts longer.","commonMistakes":["A past participle does not automatically mean past time; it often marks passive meaning."],"examples":["Make the earlier completion explicit: “Having **prepared** the visitor guide, we took a break.”","Make the earlier completion explicit: “Having **restored** the old portrait, we took a break.”"],"skill":"meaning","id":"participle-clauses-foundation-2","domain":"nonfinite","referenceIds":["bc-participles"],"readingVersion":"core-2026-09-v3"},{"title":"A completed earlier action","explanation":"Use **having + past participle** to make completion before the main action explicit. The passive equivalent is having been + participle. This is useful when sequence might otherwise be unclear, but long chains of participles can become hard to read.","pattern":"**Having checked** the map, we left.","commonMistakes":["Having checking is not the perfect-participle form: having takes a past participle."],"examples":["Reduce “who is doing the task”: “The assistant **preparing** the visitor guide is new.”","Reduce “who is doing the task”: “The assistant **restoring** the old portrait is new.”"],"skill":"contrast","id":"participle-clauses-foundation-3","domain":"nonfinite","referenceIds":["bc-participles"],"readingVersion":"core-2026-09-v3"},{"title":"Reduced relative clauses","explanation":"An -ing phrase after a noun can correspond to an active relative clause; a past-participle phrase can correspond to a passive relative. Keep the relation close to its noun and ensure that the reduction preserves the intended meaning.","pattern":"The person **waiting outside** is here. / The letter **sent yesterday** arrived.","commonMistakes":["Not every finite relative clause can be reduced without changing its meaning, tense or emphasis."],"examples":["In “Having prepared the visitor guide, the assistant left”, who performed the earlier action? → **the assistant**","In “Having restored the old portrait, the assistant left”, who performed the earlier action? → **the assistant**"],"skill":"application","id":"participle-clauses-foundation-4","domain":"nonfinite","referenceIds":["bc-participles"],"readingVersion":"core-2026-09-v3"},{"domain":"nonfinite","id":"nonfinite-forms-functions","title":"Infinitival, -ing and past-participial clauses","explanation":"Non-finite clauses use a to-infinitive, a bare infinitive, an -ing form or a past participle. They may act as complements, modifiers or adjuncts. They have no independent tense but can express earlier time through perfect constructions. Active/passive distinctions remain possible. A traditional gerund is an -ing form in a noun-like clause role.","pattern":"**to have left** · **being repaired** · **having been told**","examples":["**Swimming regularly** helps me relax.","The window **broken in the storm** was replaced."],"commonMistakes":["An -ing clause can take an object and adverb: carefully reading the letter. A deverbal noun behaves differently: the careful reading of the letter."],"referenceIds":["cambridge-nonfinite-scope","cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"nonfinite","id":"absolute-and-verbless-clauses","title":"Absolute constructions and clauses without a verb","explanation":"Some supplementary non-finite clauses have their own subject, as in the weather permitting. Others omit a recoverable form of be and are called verbless clauses. They can express time, condition, concession or circumstances. These compact patterns are common in formal descriptions and instructions, but clarity of attachment remains essential.","pattern":"**Weather permitting**, we will leave.","examples":["**Although tired**, she continued.","He stood there, **his hands in his pockets**."],"commonMistakes":["A separate subject in an absolute construction is possible; the shared-subject rule for ordinary participial adjuncts does not apply mechanically to every non-finite supplement."],"referenceIds":["cambridge-nonfinite-scope","cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"nonfinite","id":"dangling-and-perfect-participles","title":"Participial attachment, anteriority and passive meaning","explanation":"An ordinary supplementary participial clause usually takes its understood subject from the main clause. A perfect participle presents its event as earlier than the main event; a passive participle presents the understood subject as affected. If the intended actor differs, supply it explicitly or rewrite the clause.","pattern":"**Having checked** the route, we left.","examples":["**Warned about the ice**, the driver slowed down.","**After I read the report**, the error became clear."],"commonMistakes":["Reading the report, the error became clear misleadingly makes the error the reader. Conventional speaker-oriented expressions such as generally speaking are established exceptions."],"referenceIds":["cambridge-nonfinite-scope","cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["**Walking home**, she called her brother.","**Kept cool**, the food lasts longer.","**Having checked** the map, we left.","The person **waiting outside** is here. / The letter **sent yesterday** arrived."],"readingVersion":"core-2026-09-v4"},"stage":"6 · Advanced control","prerequisites":["reporting-verb-patterns"],"readingReferenceIds":["bc-participles","cambridge-nonfinite-scope","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='participle-clauses'
